package com.hbm.missile.completion.volcano;
import com.hbm.block.fluid.HbmWorldFluids;import com.hbm.bomb.conventional.ShrapnelProjectile;import com.hbm.explosion.ExplosionNT;import com.hbm.explosion.ExplosionNT.ExAttrib;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.levelgen.Heightmap;
/** Entire original BlockVolcano.TileEntityVolcanoCore chamber/channel/growth/smolder/burst behavior. */
public final class VolcanoBlockEntity extends BlockEntity {
 public int volcanoTimer;public VolcanoBlockEntity(BlockPos pos,BlockState state){super(VolcanoContent.ENTITY.get(),pos,state);}private boolean radioactive(){return getBlockState().getBlock() instanceof VolcanoBlock b&&b.radioactive;}private int meta(){return getBlockState().getValue(VolcanoBlock.META);}private Block lava(){return HbmWorldFluids.block(radioactive()?"rad_lava_block":"volcanic_lava_block");}private List<ExAttrib> attributes(){return Arrays.asList(ExAttrib.NODROP,radioactive()?ExAttrib.LAVA_R:ExAttrib.LAVA_V,ExAttrib.NOSOUND,ExAttrib.ALLMOD,ExAttrib.NOHURT);}
 public static void tick(Level level,BlockPos pos,BlockState state,VolcanoBlockEntity machine){if(level instanceof ServerLevel server)machine.update(server);}
 private void update(ServerLevel level){volcanoTimer++;if(volcanoTimer%10==0){if(meta()!=4){blastChannel(level);raiseMagma(level);}double chamber=meta()==4?15:0;if(chamber>0)blastChamber(level,chamber);if(meta()==4)meltSurface(level,50,50,10);if(meta()!=4){spawnBlobs(level);VolcanoSmokeEffects.send(level,worldPosition.getX()+.5,worldPosition.getY()+10,worldPosition.getZ()+.5);}surroundLava(level);}int rate=switch(meta()){case 1->60*60*20;case 2,3->60*60*20/250;default->10;};if(volcanoTimer>=rate){volcanoTimer=0;if(VolcanoBlock.growing(meta())&&worldPosition.getY()<200){level.setBlock(worldPosition.above(),getBlockState(),3);level.setBlock(worldPosition,lava().defaultBlockState(),3);return;}else if(VolcanoBlock.extinguishing(meta())){level.setBlock(worldPosition,lava().defaultBlockState(),3);return;}}setChanged();}
 private void blastChannel(ServerLevel level){var p=worldPosition;new ExplosionNT(level,null,p.getX()+.5,p.getY()+level.random.nextInt(15)+1.5,p.getZ()+.5,7).addAllAttrib(attributes()).explode();int bottom=level.getMinBuildHeight();double x=p.getX()+.5+level.random.nextGaussian()*3;int y=bottom+level.random.nextInt(Math.max(1,p.getY()-bottom+1));new ExplosionNT(level,null,x,y,p.getZ()+.5+level.random.nextGaussian()*3,10).addAllAttrib(attributes()).explode();}
 private void blastChamber(ServerLevel level,double size){var p=worldPosition;for(int i=0;i<2;i++){double distance=size/(i+1);new ExplosionNT(level,null,p.getX()+.5+level.random.nextGaussian()*distance,p.getY()+.5+level.random.nextGaussian()*distance,p.getZ()+.5+level.random.nextGaussian()*distance,7).addAllAttrib(attributes()).explode();}}
 private void meltSurface(ServerLevel level,int count,double radius,double depth){for(int i=0;i<count;i++){int x=(int)Math.floor(worldPosition.getX()+level.random.nextGaussian()*radius),z=(int)Math.floor(worldPosition.getZ()+level.random.nextGaussian()*radius),y=level.getHeight(Heightmap.Types.WORLD_SURFACE,x,z)+1-(int)Math.floor(Math.abs(level.random.nextGaussian()*depth));var p=new BlockPos(x,y,z);var state=level.getBlockState(p);if(!state.isAir()&&state.getBlock().getExplosionResistance()<Blocks.OBSIDIAN.getExplosionResistance())level.setBlock(p,state.isSolidRender(level,p)?lava().defaultBlockState():Blocks.AIR.defaultBlockState(),3);}}
 private void raiseMagma(ServerLevel level){var p=worldPosition.offset(-10+level.random.nextInt(21),level.random.nextInt(11),-10+level.random.nextInt(21));if(level.getBlockState(p).isAir()&&level.getBlockState(p.below()).is(lava()))level.setBlock(p,lava().defaultBlockState(),3);}
 private void surroundLava(ServerLevel level){for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(x!=0||y!=0||z!=0)level.setBlock(worldPosition.offset(x,y,z),lava().defaultBlockState(),3);}
 private void spawnBlobs(ServerLevel level){for(int i=0;i<3;i++){var fragment=new ShrapnelProjectile(level,worldPosition.getX()+.5,worldPosition.getY()+1.5,worldPosition.getZ()+.5);double y=1+level.random.nextDouble();fragment.setDeltaMovement(level.random.nextGaussian()*.2,y,level.random.nextGaussian()*.2);if(radioactive())fragment.setRadVolcano(true);else fragment.setVolcano(true);level.addFreshEntity(fragment);}}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putInt("timer",volcanoTimer);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);volcanoTimer=tag.getInt("timer");}
}
